/* Send an OpenPGP key to all keyservers.  The key in {DATA,DATALEN}
   is expected to be in OpenPGP binary transport format.  The metadata
   in {INFO,INFOLEN} is in colon-separated format (concretely, it is
   the output of 'gpg --list-keys --with-colons KEYID').  This function
   may modify DATA and INFO.  If this is a problem, then the caller
   should create a copy.  */
gpg_error_t
ks_action_put (ctrl_t ctrl, uri_item_t keyservers,
	       void *data, size_t datalen,
	       void *info, size_t infolen)
{
  gpg_error_t err = 0;
  gpg_error_t first_err = 0;
  int any_server = 0;
  uri_item_t uri;
  uri_item_t upload_uri = NULL;

  (void) info;
  (void) infolen;


#if USE_LDAP
  /* Check whether we have an upload only server and save the first
   * one.  Fixme: We should do the parsing when loading the list of
   * ldap servers to keep the upload flags in the uri_item_t.   */
  for (uri = keyservers; uri && !upload_uri; uri = uri->next)
    {
      ldap_server_t server;

      if (!uri->parsed_uri->opaque)
        continue;
      server = ldapserver_parse_one (uri->parsed_uri->path, NULL, 0);
      if (server && server->upload)
        {
          if (DBG_LDAP)
            log_debug ("found upload-only server '%s'\n",
                       uri->parsed_uri->path);
          upload_uri = uri;  /* found */
        }
      ldapserver_list_free (server);
    }
#endif /*USE_LDAP*/


  for (uri = keyservers; !err && uri; uri = uri->next)
    {
      int is_http = uri->parsed_uri->is_http;
      int is_ldap = 0;

      /* If we have an upload server skip all other servers.  */
      if (upload_uri && upload_uri != uri)
        continue;

#if USE_LDAP
      is_ldap = (!strcmp (uri->parsed_uri->scheme, "ldap")
                 || !strcmp (uri->parsed_uri->scheme, "ldaps")
                 || !strcmp (uri->parsed_uri->scheme, "ldapi")
                 || uri->parsed_uri->opaque);
#endif

      if (is_http || is_ldap)
        {
          any_server = 1;
#if USE_LDAP
	  if (is_ldap)
	    err = ks_ldap_put (ctrl, uri->parsed_uri, data, datalen,
			       info, infolen);
	  else
#endif
	    {
	      err = ks_hkp_put (ctrl, uri->parsed_uri, data, datalen);
	    }
          if (err)
            {
              first_err = err;
              err = 0;
            }
        }
    }

  if (!any_server)
    err = gpg_error (GPG_ERR_NO_KEYSERVER);
  else if (!err && first_err)
    err = first_err;
  return err;
}



/* Delete an OpenPGP key from all KEYSERVERS which use LDAP.  The key
 * is specifified by PATTERNS.  */
gpg_error_t
ks_action_del (ctrl_t ctrl, uri_item_t keyservers, strlist_t fprlist)
{
  gpg_error_t err = 0;
  gpg_error_t first_err = 0;
  int any_server = 0;
  uri_item_t uri;

  for (uri = keyservers; uri; uri = uri->next)
    {
#if USE_LDAP
      if ( !strcmp (uri->parsed_uri->scheme, "ldap")
           || !strcmp (uri->parsed_uri->scheme, "ldaps")
           || !strcmp (uri->parsed_uri->scheme, "ldapi")
           || uri->parsed_uri->opaque )
        {
          any_server = 1;
          err = ks_ldap_del (ctrl, uri->parsed_uri, fprlist);
          if (err && !first_err)
            first_err = err;
        }
#endif
    }

  if (!any_server)
    err = gpg_error (GPG_ERR_NO_KEYSERVER); /* No LDAP keyserver */
  else if (!err && first_err)
    err = first_err;
  return err;
}


/* Query the default LDAP server or the one given by URL using
 * the filter expression FILTER.  Write the result to OUTFP.  */
gpg_error_t
ks_action_query (ctrl_t ctrl, const char *url, unsigned int ks_get_flags,
                 const char *filter, char **attrs,
                 gnupg_isotime_t newer, estream_t outfp)
{
#if USE_LDAP
  gpg_error_t err;
  estream_t infp = NULL;
  uri_item_t puri;  /* The broken down URI (only one item used).  */

  if (!url && (ks_get_flags & KS_GET_FLAG_ROOTDSE))
    url = "ldap://";

  err = ks_action_parse_uri (url, &puri);
  if (err)
    return err;

  if ((ks_get_flags & KS_GET_FLAG_ROOTDSE))
    {
      /* Reset authentication for a serverless connection.  */
      puri->parsed_uri->ad_current = 0;
      puri->parsed_uri->auth = NULL;
    }

  if (!strcmp (puri->parsed_uri->scheme, "ldap")
      || !strcmp (puri->parsed_uri->scheme, "ldaps")
      || !strcmp (puri->parsed_uri->scheme, "ldapi")
      || puri->parsed_uri->opaque)
    {
      err = ks_ldap_query (ctrl, puri->parsed_uri, ks_get_flags, filter,
                           attrs, newer, &infp);
      if (!err)
        err = copy_stream (infp, outfp);
    }
  else
    err = gpg_error (GPG_ERR_CONFIGURATION); /* No LDAP server known.  */

  es_fclose (infp);
  release_uri_item_list (puri);
  return err;

#else /* !USE_LDAP */
  (void)ctrl;
  (void)url;
  (void)ks_get_flags;
  (void)filter;
  (void)attrs;
  (void)newer;
  (void)outfp;
  return gpg_error (GPG_ERR_NOT_IMPLEMENTED);
#endif
}

