  domain_orig = domain;

  /* Let's check whether we already know that the domain does not
   * support WKD.  */
  if (is_wkd_query)
    {
      if (domaininfo_is_wkd_not_supported (domain_orig))
        {
          err = gpg_error (GPG_ERR_NO_DATA);
          dirmngr_status_printf (ctrl, "NOTE", "wkd_cached_result %u", err);
          goto leave;
        }
