       * query (with a different port and socket type, though) will be
       * done later by http function.  */
      err = resolve_dns_name (ctrl, domainbuf, 0, 0, 0, &aibuf, NULL);
      if (err)
        {
          err = 0;
          xfree (domainbuf);
          domainbuf = NULL;
