              if (srvs[i].port)
                wkd_port = srvs[i].port;
              break;
            }
        }
      xfree (srvs);
    }

  xfree (uri);
  err = wkd_make_url (mbox,
                      opt_submission_addr? WKD_REQUEST_SUBMISSION :
                      opt_policy_flags? WKD_REQUEST_POLICY :
                      WKD_REQUEST_KEY,
                      domain, wkd_port,
                      subdomain_mode? domain_orig : NULL,
                      &uri);
  if (err)
    goto leave;

  if (is_wkd_query)
    {
      char portstr[20] = { 0 };

      no_log = 1;
      if (wkd_port)
        snprintf (portstr, sizeof portstr, ":%u", wkd_port);
      err = dirmngr_status_printf (ctrl, "SOURCE", "https://%s%s",
                                   domain, portstr);
      if (err)
        goto leave;
    }

  /* Setup an output stream and perform the get.  */
  {
    estream_t outfp;
    int from_cache = 0;

    outfp = ctx? es_fopencookie (ctx, "w", data_line_cookie_functions) : NULL;
    if (!outfp && ctx)
      err = set_error (GPG_ERR_ASS_GENERAL,
                       "error setting up a data stream");
    else
      {
        if (ctrl->server_local)
          {
            if (no_log)
              ctrl->server_local->inhibit_data_logging = 1;
            ctrl->server_local->inhibit_data_logging_now = 0;
            ctrl->server_local->inhibit_data_logging_count = 0;
          }
        if (is_wkd_query && opt.wkd_cache_ttl)
          err = wkd_fetch_cached (ctrl, uri, opt.wkd_cache_ttl,
                                  ks_action_fetch, outfp, &from_cache,
                                  gnupg_get_time ());
        else
          err = ks_action_fetch (ctrl, uri, outfp);
        es_fclose (outfp);
        if (ctrl->server_local)
          ctrl->server_local->inhibit_data_logging = 0;
        if (from_cache)
          dirmngr_status_printf (ctrl, "NOTE", "wkd_cached_result %u", 0);

        /* Register the result under the domain name of MBOX. */
        switch (gpg_err_code (err))
          {
          case 0:
            domaininfo_set_wkd_supported (domain_orig);
            break;

          case GPG_ERR_NO_NAME:
            /* There is no such domain.  */
            domaininfo_set_no_name (domain_orig);
            break;

          case GPG_ERR_NO_DATA:
            if (is_wkd_query && ctrl->server_local)
              {
                /* Mark that and schedule a check.  */
                domaininfo_set_wkd_not_found (domain_orig);
                workqueue_add_task (task_check_wkd_support, domain_orig,
                                    ctrl->server_local->session_id, 1);
              }
            else if (opt_policy_flags) /* No policy file - no support.  */
              domaininfo_set_wkd_not_supported (domain_orig);
            break;

          case GPG_ERR_WRONG_NAME:
            if (is_wkd_query && subdomain_mode)
              {
                /* Some sites accidently use the "openpgpkey."
                 * subdomain but do not have it in their certificate.
                 * In this case we try again without subdomain but
                 * keep the original error code.  */
                subdomain_mode = 0;
                try_without_subdomain = 1;
                xfree (domainbuf);
                domainbuf = NULL;
                domain = domain_orig;
                if (opt.verbose)
                  log_info ("retrying without \"openpgpkey\" sub-domain\n");
                goto again;
              }
            break;

          default:
            /* Don't register other errors.  */
            break;
          }
      }
  }

 leave:
  if (try_without_subdomain && err)
    err = gpg_error (GPG_ERR_WRONG_NAME);
  xfree (uri);
  xfree (mbox);
  xfree (domainbuf);
  return err;
}


