        {
          next = item->next;
          xfree (item->url);
          xfree (item->data);
          xfree (item);
        }
      wkd_cache[bucket] = NULL;
    }
  wkd_cache_items = 0;
  wkd_cache_bytes = 0;
  unlock_wkd_cache ();
