static char *
stream_to_string (estream_t fp)
{
  long len;
  char *buffer;
  size_t nread;

  len = es_ftell (fp);
  if (len < 0 || es_fseek (fp, 0, SEEK_SET))
    return NULL;
  buffer = xtrymalloc (len + 1);
  if (!buffer)
    return NULL;
  if (len && es_read (fp, buffer, len, &nread))
    {
      xfree (buffer);
      return NULL;
    }
  buffer[len] = 0;
  return buffer;
}


